import{_ as t,c as a,o as i,ae as n}from"./chunks/framework.CyJo7YO6.js";const g=JSON.parse('{"title":"Whanos Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"Devs/README.md","filePath":"Devs/README.md"}'),o={name:"Devs/README.md"};function r(l,e,s,c,u,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="whanos-documentation" tabindex="-1">Whanos Documentation <a class="header-anchor" href="#whanos-documentation" aria-label="Permalink to &quot;Whanos Documentation&quot;">​</a></h1><p>Welcome to the Whanos infrastructure documentation. This directory contains comprehensive guides to help you understand, deploy, and maintain your Whanos infrastructure.</p><h2 id="📚-documentation-index" tabindex="-1">📚 Documentation Index <a class="header-anchor" href="#📚-documentation-index" aria-label="Permalink to &quot;📚 Documentation Index&quot;">​</a></h2><h3 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h3><ul><li><strong><a href="./USER_GUIDE.html">User Guide</a></strong> - Quick start guide for deploying and using Whanos</li><li><strong><a href="./DEPLOYMENT.html">Deployment Guide</a></strong> - Step-by-step deployment instructions</li></ul><h3 id="technical-documentation" tabindex="-1">Technical Documentation <a class="header-anchor" href="#technical-documentation" aria-label="Permalink to &quot;Technical Documentation&quot;">​</a></h3><ul><li><strong><a href="./ARCHITECTURE.html">Architecture Overview</a></strong> - System architecture and component interactions</li><li><strong><a href="./ANSIBLE.html">Ansible Automation</a></strong> - Detailed Ansible playbook documentation</li><li><strong><a href="./JENKINS.html">Jenkins Pipeline</a></strong> - Jenkins configuration and job DSL details</li><li><strong><a href="./HELM.html">Helm Charts</a></strong> - Kubernetes deployment with Helm</li><li><strong><a href="./CONFIGURATION.html">Configuration Reference</a></strong> - All configuration options and environment variables</li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><ul><li><strong><a href="./TROUBLESHOOTING.html">Troubleshooting</a></strong> - Common issues and solutions</li><li><strong><a href="./SECURITY.html">Security</a></strong> - Security best practices and considerations</li></ul><h2 id="🚀-quick-links" tabindex="-1">🚀 Quick Links <a class="header-anchor" href="#🚀-quick-links" aria-label="Permalink to &quot;🚀 Quick Links&quot;">​</a></h2><ul><li><strong>First time deploying Whanos?</strong> → Start with the <a href="./USER_GUIDE.html">User Guide</a></li><li><strong>Want to understand how it works?</strong> → Read the <a href="./ARCHITECTURE.html">Architecture Overview</a></li><li><strong>Having issues?</strong> → Check the <a href="./TROUBLESHOOTING.html">Troubleshooting Guide</a></li></ul><h2 id="📋-project-overview" tabindex="-1">📋 Project Overview <a class="header-anchor" href="#📋-project-overview" aria-label="Permalink to &quot;📋 Project Overview&quot;">​</a></h2><p><strong>Whanos</strong> is an automated deployment infrastructure that allows developers to deploy applications into a Kubernetes cluster with a simple Git push. It supports multiple programming languages and automatically:</p><ol><li>Detects the application technology</li><li>Builds Docker images</li><li>Pushes to registries (local and Docker Hub)</li><li>Deploys to Kubernetes cluster (if configured)</li></ol><h3 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported Languages&quot;">​</a></h3><ul><li>C</li><li>Java</li><li>JavaScript</li><li>Python</li><li>Befunge</li></ul><h2 id="🛠️-technology-stack" tabindex="-1">🛠️ Technology Stack <a class="header-anchor" href="#🛠️-technology-stack" aria-label="Permalink to &quot;🛠️ Technology Stack&quot;">​</a></h2><ul><li><strong>Ansible</strong> - Infrastructure automation</li><li><strong>Jenkins</strong> - CI/CD orchestration</li><li><strong>Docker</strong> - Containerization</li><li><strong>Kubernetes (K3s)</strong> - Container orchestration</li><li><strong>Helm</strong> - Kubernetes package manager</li><li><strong>Docker Registry</strong> - Image storage</li></ul><h2 id="📖-documentation-structure" tabindex="-1">📖 Documentation Structure <a class="header-anchor" href="#📖-documentation-structure" aria-label="Permalink to &quot;📖 Documentation Structure&quot;">​</a></h2><p>Each documentation file follows a consistent structure:</p><ul><li><strong>Overview</strong> - High-level summary</li><li><strong>Technical Details</strong> - In-depth technical information</li><li><strong>Configuration</strong> - Setup and configuration options</li><li><strong>Examples</strong> - Practical usage examples</li><li><strong>References</strong> - Additional resources</li></ul><h2 id="🤝-contributing" tabindex="-1">🤝 Contributing <a class="header-anchor" href="#🤝-contributing" aria-label="Permalink to &quot;🤝 Contributing&quot;">​</a></h2><p>When updating documentation:</p><ol><li>Keep it clear and concise</li><li>Include practical examples</li><li>Update related documentation files</li><li>Test all commands and configurations</li></ol><h2 id="📝-license" tabindex="-1">📝 License <a class="header-anchor" href="#📝-license" aria-label="Permalink to &quot;📝 License&quot;">​</a></h2><p>This project is part of the Epitech DevOps curriculum.</p><hr><p><strong>Need help?</strong> Start with the <a href="./USER_GUIDE.html">User Guide</a> or check the <a href="./TROUBLESHOOTING.html">Troubleshooting Guide</a>.</p>',28)])])}const m=t(o,[["render",r]]);export{g as __pageData,m as default};
